func:
if (msg.topic === 'alert_duration_sec' || msg.topic === 'buzzer_freq_hz') {
    return null;
}

const foodName = (msg.food_name || msg.payload || 'Thực phẩm quét').trim();
const customIng = (msg.ingredients_input || '').trim();
const textToAnalyze = (foodName + ' ' + customIng).toLowerCase();

// Danh mục các nhóm dị ứng chính theo Đồ thị FoodOn (Level 7)
const allergenRules = [
    {
        group: "MILK / DAIRY",
        keywords: ["sữa", "bơ", "cheese", "phô mai", "whipping", "cream", "whey", "casein", "sữa tươi", "sữa đặc", "yogurt", "sữa chua", "dairy", "milk"],
        source: "Sữa bò (Cow Milk - Dairy)",
        reason: "Chứa protein Sữa (Casein/Whey) thuộc nhóm dị ứng sữa theo đồ thị FoodOn (FOODON:00001002)"
    },
    {
        group: "PEANUT",
        keywords: ["đậu phộng", "lạc", "peanut", "bơ đậu phộng", "dầu phộng", "cu đơ", "arachis"],
        source: "Đậu phộng (Peanut)",
        reason: "Chứa hợp chất protein từ hạt Đậu phộng (Arachis hypogaea) nguy cơ sốc phản vệ cao"
    },
    {
        group: "SHELLFISH",
        keywords: ["tôm", "cua", "ghẹ", "mực", "bạch tuộc", "mắm ruốc", "mắm tôm", "hải sản", "shrimp", "crab", "prawn", "lobster", "squid", "bột tôm"],
        source: "Hải sản / Giáp xác (Shellfish)",
        reason: "Chứa Tropomyosin từ động vật Giáp xác/Thân mềm theo đồ thị FoodOn (Level 7)"
    },
    {
        group: "FISH",
        keywords: ["cá", "cá hồi", "cá ngừ", "chả cá", "nước mắm", "fish", "salmon", "tuna"],
        source: "Cá (Fish Group)",
        reason: "Chứa Parvalbumin từ nhóm cá biển/cá nước ngọt theo FoodOn"
    },
    {
        group: "EGG",
        keywords: ["trứng", "lòng đỏ", "lòng trắng", "mayonnaise", "egg", "albumin", "ovalbumin"],
        source: "Trứng (Egg)",
        reason: "Chứa Ovalbumin/Ovomucoid từ trứng gia cầm theo FoodOn"
    },
    {
        group: "SOYBEAN",
        keywords: ["đậu nành", "đậu phụ", "đậu hũ", "tàu hũ", "xì dầu", "nước tương", "chao", "soy", "soya", "tofu", "lecithin", "miso"],
        source: "Đậu nành (Soybean)",
        reason: "Chứa Glycinin & Conglycinin từ họ Đậu nành theo FoodOn"
    },
    {
        group: "WHEAT / GLUTEN",
        keywords: ["bột mì", "bánh mì", "mì sợi", "mì tôm", "nui", "pasta", "hoành thánh", "lúa mì", "lúa mạch", "wheat", "gluten", "flour"],
        source: "Lúa mì & Gluten (Wheat)",
        reason: "Chứa Protein Gluten từ lúa mì gây dị ứng tiêu hóa / Celiac"
    },
    {
        group: "TREE NUTS",
        keywords: ["hạt điều", "hạnh nhân", "óc chó", "hạt dẻ", "macca", "cashew", "almond", "walnut", "hazelnut", "pistachio"],
        source: "Hạt cây dinh dưỡng (Tree Nuts)",
        reason: "Chứa Protein kháng nhiệt từ hạt cây thuộc nhóm dị ứng nghiêm trọng"
    },
    {
        group: "SESAME",
        keywords: ["mè", "vừng", "dầu mè", "sốt mè", "sesame"],
        source: "Hạt mè / Vừng (Sesame)",
        reason: "Chứa Ses i 1 protein từ vừng/mè theo FoodOn"
    }
];

let warnings = [];
let detectedIngredients = [];

// Phân tích văn bản đối chiếu quy tắc FoodOn
for (let rule of allergenRules) {
    for (let kw of rule.keywords) {
        if (textToAnalyze.includes(kw)) {
            detectedIngredients.push(kw);
            warnings.push({
                scanned_item: kw,
                allergen_source: rule.source,
                reason: rule.reason
            });
            break;
        }
    }
}

// Loại trừ trùng lặp
detectedIngredients = Array.from(new Set(detectedIngredients));

const isSafe = (warnings.length === 0);

let ingredientsText = customIng;
if (!ingredientsText) {
    if (detectedIngredients.length > 0) {
        ingredientsText = detectedIngredients.join(", ") + ", gia vị tự nhiên";
    } else {
        ingredientsText = "nguyên liệu tự nhiên, nước, gia vị thanh khiết (an toàn)";
    }
}

msg.payload = {
    is_safe: isSafe,
    product_title: foodName,
    scanned_ingredients_text: ingredientsText,
    warnings: warnings,
    client_timestamp: msg.client_timestamp
};

return msg;

const isSafe = msg.payload.is_safe;
let warningText = isSafe ? "SAN PHAM AN TOAN" : "CANH BAO DI UNG!";

msg.payload = JSON.stringify({
    "is_safe": isSafe,
    "warning_text": warningText,
    "vibration_pulses": isSafe ? 1 : 2,
    "pulse_duration_ms": isSafe ? 100 : 200
});
return msg;

if (msg.topic !== 'alert_duration_sec' && msg.topic !== 'buzzer_freq_hz') {
    return null;
}

let cfg = flow.get('cfg') || {
    "type": "hardware_config",
    "alert_duration_sec": 5,
    "buzzer_freq_hz": 1500,
    "blink_rate_ms": 200,
    "safe_duration_sec": 5
};

if (msg.topic === 'alert_duration_sec') cfg.alert_duration_sec = parseInt(msg.payload);
if (msg.topic === 'buzzer_freq_hz') cfg.buzzer_freq_hz = parseInt(msg.payload);

flow.set('cfg', cfg);
msg.payload = JSON.stringify(cfg);
return msg;

let sec = flow.get('remainSec');
if (sec === undefined || sec === null) sec = 28;
sec = sec - 1;
if (sec <= 0) sec = 28;
flow.set('remainSec', sec);

const t_latency_ms = 375;
const t_latency_sec = 0.375;
const t_trigger = sec - t_latency_sec;
const isTriggerRung = t_trigger <= 5.0;

msg.payload = {
    t_remain: sec,
    t_latency_ms: t_latency_ms,
    t_trigger: t_trigger.toFixed(2),
    is_vibrate: isTriggerRung,
    status_text: isTriggerRung ? "⚠️ ĐÈN SẮP XANH - RUNG DÀI 500MS BÁO CHUẨN BỊ!" : "Dừng chờ đèn đỏ an toàn"
};
return msg;

if (msg.payload.is_vibrate && msg.payload.t_remain === 5) {
    msg.payload = JSON.stringify({
        "type": "traffic_alert",
        "vibration_pulses": 1,
        "pulse_duration_ms": 500,
        "message": "PREPARE TO DRIVE"
    });
    return msg;
}
return null;

flow.set('remainSec', 28);
const t_latency_ms = 375;
const t_latency_sec = 0.375;
const t_trigger = 28 - t_latency_sec;

msg.payload = {
    t_remain: 28,
    t_latency_ms: t_latency_ms,
    t_trigger: t_trigger.toFixed(2),
    is_vibrate: false,
    status_text: "Dừng chờ đèn đỏ an toàn (Đã đặt lại 28s)"
};
return msg;

let logs = flow.get('scanLogs') || [];

// Lấy giờ chính xác từ client
let timeStr = msg.payload.client_timestamp;
if (!timeStr) {
    const now = new Date();
    const h = String(now.getHours()).padStart(2, '0');
    const m = String(now.getMinutes()).padStart(2, '0');
    const s = String(now.getSeconds()).padStart(2, '0');
    const d = String(now.getDate()).padStart(2, '0');
    const mo = String(now.getMonth() + 1).padStart(2, '0');
    const y = now.getFullYear();
    timeStr = h + ':' + m + ':' + s + ' ' + d + '/' + mo + '/' + y;
}

const newLog = {
    id: logs.length > 0 ? (logs[0].id + 1) : 1001,
    time: timeStr,
    product_name: msg.payload.product_title || 'Món ăn tự chọn',
    ingredients: msg.payload.scanned_ingredients_text || 'thành phần tự nhiên',
    is_safe: msg.payload.is_safe
};

logs.unshift(newLog);
if (logs.length > 12) logs.pop();
flow.set('scanLogs', logs);

msg.payload = logs;
return msg;

if (msg.payload === 'CLEAR_LOGS') {
    flow.set('scanLogs', []);
    msg.payload = [];
    return msg;
}

// REFRESH_LOGS - Luôn trả về danh sách hiện tại
let logs = flow.get('scanLogs') || [];
msg.payload = logs;
return msg;
